mapper.select:
select e.id, e.project_id, p.short_name projectName, e.enclosure_plan_id, e.area_id, e.dictionary_id, d.label dictionaryName, e.bool_status_enum, e.category, e.name, e.serial_number, e.brand, e.plate, e.color, e.material, e.coating, e.plating, e.weight, e.total_weight, e.thickness, e.width, e.unfolded_width, e.length, e.unit, e.quantity, e.accounting_volume, e.total_length as total_length, e.surface_area surface_area, e.total_area as total_area, e.remark, e.business_id, e.attachment_id, e.bend_times, e.weight_meter, e.user_id, u.name user_name, e.scheduling_quantity, e.produced_quantity, e.category, e.create_time from tech_enclosure e left join sys_user u on e.user_id = u.id and u.bool_delete_enum = 0 left join sys_dictionary d on e.dictionary_id = d.id and d.bool_delete_enum = 0 left join contract_project p on e.project_id = p.id and p.bool_delete_enum = 0 WHERE e.bool_delete_enum = 0
and e.project_id = #{projectId}
and d.id = #{dictionaryId}
and e.enclosure_plan_id = #{enclosurePlanId}
and e.area_id = #{areaId}
and e.bool_status_enum = #{boolStatusEnum}
and e.name like concat('%',#{name},'%')
and e.serial_number like concat('%',#{serialNumber},'%')
and e.plate like concat('%',#{plate},'%')
and e.color like concat('%',#{color},'%')
and e.thickness = #{thickness}
and e.weight = #{weight}
order by e.id asc;

SELECT plate, color, brand, SUM(IFNULL(quantity,0)) quantity, SUM(IFNULL(total_area,0))/1000000 total_area, SUM(IFNULL(total_length,0))/1000 total_length, SUM(IFNULL(weight, 0)) weight
FROM tech_enclosure WHERE bool_delete_enum = 0 AND category = #{category}
and project_id = #{projectId}
AND monomer_id = #{monomerId}
GROUP BY plate , color, brand

SELECT plate, color, thickness, brand, width, SUM(IFNULL(quantity, 0)) quantity, SUM(IFNULL(total_area, 0))/1000000 total_area, SUM(IFNULL(total_length, 0))/1000 total_length, SUM(IFNULL(weight, 0)) weight
FROM tech_enclosure WHERE bool_delete_enum = 0 AND category = #{category}
and project_id = #{projectId}
AND monomer_id = #{monomerId}
GROUP BY plate, color, thickness, brand, width

SELECT color, thickness, brand, unfolded_width, SUM(IFNULL(quantity, 0)) quantity, SUM(IFNULL(total_area, 0))/1000000 total_area, SUM(IFNULL(total_length, 0))/1000 total_length, SUM(IFNULL(weight, 0)) weight FROM tech_enclosure WHERE bool_delete_enum = 0 AND category = #{category}
and project_id = #{projectId}
AND monomer_id = #{monomerId}
GROUP BY color, thickness, brand, unfolded_width

SELECT plate, thickness, color, brand, SUM(IFNULL(quantity,0)) quantity, SUM(IFNULL(total_area,0))/1000000 total_area, SUM(IFNULL(total_length,0))/1000 total_length, SUM(IFNULL(weight, 0)) weight FROM tech_enclosure WHERE bool_delete_enum = 0 AND category = #{category}
and project_id = #{projectId}
AND monomer_id = #{monomerId}
GROUP BY plate, thickness, color, brand

select ifnull(sum(quantity),0) quantity,
ifnull(sum(total_length),0)/1000 mete,
ifnull(sum(total_area),0)/1000000 mete_two
from tech_enclosure
where bool_delete_enum = 0

    and project_id = #{projectId}


    and monomer_id = #{monomerId}


    and area_id = #{areaId}

select IFNULL(SUM(total_area), 0)
from tech_enclosure
where area_id = #{areaId}
  and category = #{productType}
  and bool_status_enum = 0

select project_id,category,ifnull(sum(quantity),0) quantity, ifnull(sum(total_length),0)/1000 mete from tech_enclosure where bool_delete_enum = 0
and project_id = #{projectId}
group by project_id,category

select area_id,category,ifnull(sum(quantity),0) quantity, ifnull(sum(total_length),0)/1000 mete from tech_enclosure where bool_delete_enum = 0
and project_id = #{projectId}
group by area_id,category

select m.`id` 'monomer.id', m.`name` 'monomer.name', ifnull(sum(a.quantity), 0) quantity,
       ifnull(sum(a.total_length), 0) / 1000 total_length
from tech_enclosure a
         inner join plan_monomer m on m.id = a.monomer_id and m.bool_delete_enum = 0

    INNER JOIN sys_monomer_user_link AS link ON m.monomer_id = link.monomer_id AND link.bool_delete_enum = 0 AND link.deepened_person_id = #{userId}

where a.bool_delete_enum = 0
  and a.project_id = #{projectId}
  and a.category = #{category}
group by m.id, m.name

select d.`id` 'area.id', d.`name` 'area.name', d.axis 'area.axis', ifnull(sum(a.quantity), 0) quantity,
       ifnull(sum(a.total_length), 0) / 1000 total_length
from tech_enclosure a
         inner join plan_area d on d.id = a.area_id and d.bool_delete_enum = 0

    INNER JOIN sys_monomer_user_link AS link ON d.monomer_id = link.monomer_id AND link.bool_delete_enum = 0 AND link.deepened_person_id = #{userId}

where a.bool_delete_enum = 0
  and a.monomer_id = #{monomerId}
  and a.category = #{category}
group by d.id, d.name

SELECT
IFNULL(SUM(e.total_length), 0)/1000 as total_length,
IFNULL(SUM(e.total_area), 0)/1000000 as total_area,
IFNULL(SUM(e.quantity), 0) as total_quantity
FROM tech_enclosure as e
WHERE e.bool_delete_enum = 0

    and e.project_id = #{projectId}


    and e.category = #{category}


    and e.enclosure_plan_id = #{enclosurePlanId}


    and e.bool_status_enum = #{boolStatusEnum}


    and e.name like concat('%',#{name},'%')


    and e.serial_number like concat('%',#{serialNumber},'%')


    and e.plate like concat('%',#{plate},'%')


    and e.color like concat('%',#{color},'%')


    and e.thickness = #{thickness}


    and  e.weight = #{weight}

SELECT
IFNULL(SUM(e.total_length), 0)/1000 as total_length,
IFNULL(SUM(e.total_area), 0)/1000000 as total_area,
IFNULL(SUM(e.quantity), 0) as total_quantity
FROM tech_enclosure as e
WHERE e.bool_delete_enum = 0

    and e.project_id = #{projectId}


    and e.dictionary_id = #{dictionaryId}


    and e.area_id = #{areaId}


    and e.bool_status_enum = #{boolStatusEnum}


    and e.name like concat('%',#{name},'%')


    and e.serial_number like concat('%',#{serialNumber},'%')

select *
from tech_enclosure
where id = #{id}

SELECT pro.serial_number 'project.serialNumber' , pro.short_name 'project.shortName', pro.`name` 'project.name', pro.id 'project.id', pro.end_date 'project.endDate', enc.id 'productId', enc.quantity 'quantity', enc.subscribe_quantity, enc.scheduling_quantity 'schedulingQuantity' FROM tech_enclosure enc LEFT JOIN contract_project pro ON enc.project_id=pro.id WHERE enc.bool_delete_enum=0 and enc.bool_status_enum=1
AND DATE_FORMAT( pro.create_time, '%Y' ) = #{year}
and ( pro.name like concat('%',#{name},'%') or pro.short_name like concat('%',#{name},'%') or pro.serial_number like concat('%',#{name},'%') )

SELECT cp.id project_id, cp.short_name project_short_name, cp.serial_number project_serial_number, pm.id monomer_id, pm.`name` monomer_name, pa.id area_id, pa.`name` area_name, case when en.scheduling_quantity = 0 then 1 when en.scheduling_quantity > 0 and en.scheduling_quantity < en.quantity then 2 else 4 end status FROM tech_enclosure en LEFT JOIN contract_project cp ON en.project_id = cp.id AND en.bool_delete_enum = 0 LEFT JOIN plan_monomer pm ON en.monomer_id = pm.id AND pm.bool_delete_enum = 0 LEFT JOIN plan_area pa ON en.area_id = pa.id AND pa.bool_delete_enum = 0 WHERE en.bool_delete_enum = 0 and pa.type = 0 AND en.bool_status_enum = 1 AND DATE_FORMAT( cp.create_time, '%Y') = #{year}
and (cp.short_name like concat('%',#{name},'%') or cp.name like concat('%',#{name},'%'))
and en.scheduling_quantity + en.subscribe_quantity < en.quantity

select a.* from ( select a.id, a.`name`, a.plate specification, a.serial_number, a.create_time, c.id 'project.id', c.name 'project.name', c.serial_number 'project.serial_number', c.short_name 'project.short_name', d.id 'monomer.id', d.name 'monomer.name', e.id 'area.id', e.name 'area.name' from tech_enclosure a left join mes_enclosure_produce_team_report b on a.id = b.product_id left join contract_project c on a.project_id = c.id left join plan_monomer d on a.monomer_id = d.id left join plan_area e on a.area_id = e.id where a.bool_delete_enum = 0 and b.bool_delete_enum = 0 and a.serial_number like concat( '%', #{serialNumber}, '%' )
and a.project_id = #{projectId}
and a.monomer_id = #{monomerId}
and a.area_id = #{areaId}
group by a.id, c.id, d.id, e.id, a.serial_number, a.plate ) a order by a.create_time desc
